//! `xtask schema-diff` as a test: the `schemars` schema of `CalliopeAttrs` matches the pydantic
//! schema (`tests/fixtures/pydantic_calliope_attrs.json`, regenerated by
//! `cargo run -p xtask -- schema-diff --update`) in structure, types, constraints and defaults.

use calliope_schema::{CalliopeAttrs, json_schema, schema_diff};

#[test]
fn schema_matches_pydantic() {
    let fixture = include_str!("fixtures/pydantic_calliope_attrs.json");
    let pydantic: serde_json::Value = serde_json::from_str(fixture).unwrap();
    let ours = json_schema::<CalliopeAttrs>();
    let diffs = schema_diff::diff(&pydantic, &ours);
    assert!(
        diffs.is_empty(),
        "{} differences (left: pydantic, right: Rust):\n{}",
        diffs.len(),
        diffs.join("\n")
    );
}

/// The comparison is not vacuous: changed defaults, types and fields are reported.
#[test]
fn schema_diff_detects_changes() {
    let fixture = include_str!("fixtures/pydantic_calliope_attrs.json");
    let pydantic: serde_json::Value = serde_json::from_str(fixture).unwrap();
    for (pointer, new) in [
        (
            "/$defs/Init/properties/datetime_format/default",
            serde_json::json!("x"),
        ),
        (
            "/$defs/Init/properties/broadcast_input_data/type",
            serde_json::json!("string"),
        ),
        ("/$defs/Bounds/properties/max/default", serde_json::json!(3)),
    ] {
        let mut changed = pydantic.clone();
        *changed.pointer_mut(pointer).unwrap() = new;
        assert!(
            !schema_diff::diff(&pydantic, &changed).is_empty(),
            "{pointer}"
        );
    }
    let mut changed = pydantic.clone();
    changed
        .pointer_mut("/$defs/SolveSpores/properties")
        .unwrap()
        .as_object_mut()
        .unwrap()
        .remove("number");
    assert!(!schema_diff::diff(&pydantic, &changed).is_empty());
}
